import env from '@next/env';import {getPgPool} from '../server/database/pgClient.js';import fs from 'node:fs';env.loadEnvConfig(process.cwd());const pool=getPgPool(),db=await pool.connect();const results={};try{await db.query('BEGIN READ ONLY');await db.query("SET LOCAL statement_timeout='15000ms'");results.counts=(await db.query("SELECT relname,n_live_tup FROM pg_stat_user_tables WHERE schemaname='public' AND relname IN ('comercial_cuentas','comercial_contactos','comercial_propuestas_db','comercial_contratos','tesoreria_ordenes','produccion_contenidos','produccion_control_redaccion','tesoreria_movimientos_bancarios','administracion_facturas_clientes','administracion_facturas_proveedores','tesoreria_cargos_recurrentes') ORDER BY relname")).rows;results.orders=(await db.query("SELECT count(*)::int total,count(*) FILTER(WHERE cancelada AND NOT cobrada)::int cancelled_unpaid,count(*) FILTER(WHERE NOT cobrada AND fecha_teorica_cobro ~ '^\\d{4}-')::int unpaid_iso_dates,count(*) FILTER(WHERE NOT cobrada AND fecha_teorica_cobro ~ '^\\d{1,2}/\\d{1,2}/\\d{4}$')::int unpaid_slash_dates FROM tesoreria_ordenes")).rows[0];results.verifactu=(await db.query('SELECT status,count(*)::int total FROM fiscal_verifactu_envios GROUP BY status')).rows;results.indexes=(await db.query("SELECT tablename,indexname FROM pg_indexes WHERE schemaname='public' AND tablename IN ('tesoreria_ordenes','tesoreria_aplicaciones_cobro','produccion_contenidos','agentes_db') ORDER BY tablename,indexname")).rows;results.schema=(await db.query("SELECT column_name FROM information_schema.columns WHERE table_schema='public' AND table_name='tesoreria_cargos_recurrentes' AND column_name IN ('termina_planificacion','planificado_hasta','banco_pago')")).rows;results.pending=(await db.query("SELECT count(*) FILTER(WHERE NOT cobrada AND cancelada AND p3_income_date(fecha_teorica_cobro)<current_date)::int cancelled_overdue,count(*) FILTER(WHERE NOT cobrada AND NOT cancelada AND p3_income_date(fecha_teorica_cobro)<current_date)::int active_overdue FROM tesoreria_ordenes")).rows[0];await db.query('ROLLBACK');fs.writeFileSync('outputs/auditoria-datos-20261005.json',JSON.stringify(results,null,2));console.log(JSON.stringify(results,null,2));}catch(e){await db.query('ROLLBACK');console.log('READ ONLY AUDIT ERROR:',e.message);}finally{db.release();await pool.end();}